DROP TABLE IF EXISTS `tbl_awb`;
CREATE TABLE `tbl_awb` (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `api_uuid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第三方主键(第三方接口id)',
  `prefix` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '前缀',
  `cargo_no` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `awb_no` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '运单号',
  `awb_carrier` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '运单承运人',
  `international` smallint DEFAULT NULL COMMENT '国内国际 1、国内  2、国际',
  `type` smallint DEFAULT NULL COMMENT '制单类型:0:代理人制单、1:货站制单',
  `way_bill_status` smallint DEFAULT NULL COMMENT '制单状态:0:草稿、1:提交、2:作废',
  `cargo_type` smallint DEFAULT NULL COMMENT '运单类型 1、运单，2、邮单，3、其他，4、更改单，5、作废单',
  `agent_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '代理人编码',
  `agent_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '代理人名称',
  `flight_no` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '航班号',
  `carrier` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '承运人',
  `airline_icao` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '航司ICAO码',
  `airline_icao1` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '航司ICAO码(第一程)',
  `flight_date` date NOT NULL COMMENT '航班日期',
  `dep` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '始发站',
  `dep_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '始发站名称',
  `dest` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '目的站',
  `dest1` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '第一目的站',
  `arr` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '中转站',
  `flight_nature` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '航程',
  `dest_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '目的站名称',
  `flight_no2` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第二航班号',
  `airline_icao2` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '航司ICAO码(第二程)',
  `flight_date2` date DEFAULT NULL COMMENT '第二航班日期',
  `carrier2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第二承运人',
  `dep2` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第二始发站',
  `dest2` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第二到达站',
  `flight_no3` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第三航班号',
  `airline_icao3` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '航司ICAO码(第三程)',
  `carrier3` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第三承运人',
  `flight_date3` date DEFAULT NULL COMMENT '第三航班日期',
  `dep3` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第三始发站',
  `dest3` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '第三到达站',
  `rate_class` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '运价种类',
  `signature_agent` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '托运人或其代理人签字盖章',
  `signatureits_agent` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '填开人或其代理人签字、盖章',
  `custom_fee_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '自定义费用项目名称',
  `custom_fee_value` decimal(10,2) DEFAULT NULL COMMENT '自定义费用项值',
  `rate_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '运价名称',
  `rate_type` int DEFAULT NULL COMMENT '费率类型 0为正常费率 1为一票一议 2为自动计算运价',
  `ascription_type` int DEFAULT NULL COMMENT '归属类型 0代理 1货站 2航司',
  `fhr_mc` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货人名称',
  `fhr_city` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货人城市',
  `fhr_lxhm` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货人联系号码',
  `fhr_dz` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '发货人地址',
  `fhr_yb` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货人邮编',
  `fhr_gjdm` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货人国家代码',
  `fhr_fax` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货人传真',
  `fhr_contractor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货人联络人',
  `fhr_eori` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货人eori',
  `fhr_continent` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货人洲',
  `shr_fax` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人传真',
  `shr_continent` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人洲',
  `shr_contractor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人联络人',
  `shr_eori` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人eori',
  `shr_mc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人名称',
  `shr_city` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人城市',
  `shr_lxhm` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人联系号码',
  `shr_dz` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '收货人地址',
  `shr_yb` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人邮编',
  `shr_gjdm` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人国家代码',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '币种',
  `prepay` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `insurance` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '保险价值',
  `settlement_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '结算注意事项',
  `handling_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '储运注意事项',
  `issuing_agent_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '填开货运单的代理人名称',
  `issuing_agent_city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '填开货运单的代理人城市',
  `atplace` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '填开地点',
  `is_complete_put_in` smallint DEFAULT NULL COMMENT '收运是否完成  1：收运完成  0：未收运完成',
  `goods_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '品名',
  `goods_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '结算货物类型',
  `pc` int NOT NULL COMMENT '件数',
  `weight` decimal(10,2) NOT NULL COMMENT '重量',
  `charge_weight` decimal(10,2) DEFAULT NULL COMMENT '计费重量',
  `volume` decimal(30,2) DEFAULT NULL COMMENT '体积',
  `size` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '尺寸',
  `rate` decimal(10,2) DEFAULT NULL COMMENT '费率',
  `flight_fee_prepaid` decimal(10,2) DEFAULT NULL COMMENT '航空运费Prepaid',
  `flight_fee_collect` decimal(10,2) DEFAULT NULL COMMENT '航空运费Collect',
  `total_flight_fee` decimal(10,2) DEFAULT NULL COMMENT '总航空费用',
  `memo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '备注',
  `spcode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '特码',
  `packing` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '包装(暂时未使用到)',
  `is_history` smallint NOT NULL COMMENT '是否历史数据  1:是,0:不是',
  `op_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人名称',
  `op_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人Id',
  `is_delete` smallint NOT NULL COMMENT '是否删除 1:删除,0:未删除',
  `issuing_agent_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '填开货运单的代理人编码(暂时不用)',
  `dvc_prepaid` decimal(10,2) DEFAULT NULL COMMENT '声明价值附加费Prepaid',
  `dvc_collect` decimal(10,2) DEFAULT NULL COMMENT '声明价值附加费Collect',
  `sfc_prepaid` decimal(10,2) DEFAULT NULL COMMENT '地面运费Prepaid',
  `sfc_collect` decimal(10,2) DEFAULT NULL COMMENT '地面运费Collect',
  `agent_other_fee_prepaid` decimal(10,2) DEFAULT NULL COMMENT '代理人其他费用prepaid',
  `agent_other_fee_collect` decimal(10,2) DEFAULT NULL COMMENT '代理人其他费用Collect',
  `carrier_other_fee_prepaid` decimal(10,2) DEFAULT NULL COMMENT '承运人其他费用prepaid',
  `carrier_other_fee_collect` decimal(10,2) DEFAULT NULL COMMENT '承运人其他费用Collect',
  `other_request_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '其他请求代码',
  `other_request_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '其他请求内容',
  `charge_type_code` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '价格类型，对应fwbxml中的typecode字段',
  `is_draft` int DEFAULT NULL COMMENT '草稿数据(0:不是草稿，1是草稿)',
  `goods_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品代码',
  `issued_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '填开日期',
  `no_consignee_number` int DEFAULT NULL COMMENT '待收运件数',
  `no_consignee_weight` decimal(10,2) DEFAULT NULL COMMENT '待收运重量',
  `ticket_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '票证id',
  `awm_type` smallint DEFAULT NULL COMMENT '运单类型0：出港运单，1：进港运单',
  `airline_org_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '航司代码',
  `decimal_point` smallint DEFAULT NULL COMMENT '运单运费保留小数点位合法值为：-2:十位,-1:个位, 0:不保留,1:小数点后一位,2:小数点后两位',
  `rounding_rule` smallint DEFAULT NULL COMMENT '运费计算规则 合法值为 1: 四舍五入  2: 向上取整',
  `price_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '获取运价费率返回的运价id',
  `is_transit` smallint DEFAULT NULL COMMENT '是否中转（0-否 1-是）',
  `freight_department` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '国际主单使用 货运处',
  `declare_value` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT ' 运输声明价值',
  `customs_value` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT ' 海关声明价值',
  `wt_val` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT ' 航空运费付款方式  PP预付 CC到付',
  `other_val` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '其他费用付款方式  PP预付 CC到付',
  `fee_unit` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '计费单位 kg or LB',
  `slac_pc` int DEFAULT NULL COMMENT '清点件数',
  `sci` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'sci',
  `tax_collect` decimal(10,2) DEFAULT NULL COMMENT '税费collect',
  `tax_prepaid` decimal(10,2) DEFAULT NULL COMMENT '税费Prepaid',
  `total_prepaid` decimal(10,2) DEFAULT NULL COMMENT '预付总计',
  `total_collect` decimal(10,2) DEFAULT NULL COMMENT '到付总计',
  `total_amount` decimal(10,2) DEFAULT NULL COMMENT '总金额',
  `dict_settle_way` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT ' 国际制单-结算方式 Cash 月结  Term 现结',
  `settle_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '结算方式码 IATA Code',
  `account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '账号 国际主单使用，手输',
  `branch_nums` int DEFAULT NULL COMMENT '分单数量',
  `hs_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'HS Code',
  `notifier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT ' 通知人姓名',
  `notifier_phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '通知人电话',
  `agent_iata` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT ' 代理人iata编码',
  `agent_account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '代理人账号',
  `remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `maker_time` datetime DEFAULT NULL COMMENT '制单时间',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `datagram_state` smallint DEFAULT NULL COMMENT '是否发送报文：0：未发送、1：发送成功、2：发送失败',
  `vr` decimal(10,3) DEFAULT NULL COMMENT '体积重计算',
  `bill_status` smallint DEFAULT NULL COMMENT '是否开账：0：未开账、1：已开账',
  `cal_flag` smallint DEFAULT NULL COMMENT '标识 0 未计算；1 计算成功； 2 计算失败',
  `cal_time` datetime DEFAULT NULL COMMENT '最新计算时间',
  `sale_type` smallint DEFAULT NULL COMMENT '销售类型：0普通;1包舱;2包量;3短款;4更改单;',
  `check_status` smallint DEFAULT NULL COMMENT '审核状态：0未审核;1已审核',
  `checker` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核人',
  `check_time` datetime DEFAULT NULL COMMENT '审核时间',
  `cal_flight_fee` decimal(10,2) DEFAULT NULL COMMENT '计算后航空费用',
  `cal_fuel_fee` decimal(10,2) DEFAULT NULL COMMENT '计算后燃油附加费',
  `cal_awc` decimal(10,2) DEFAULT NULL COMMENT '计算后制单费',
  `cal_dvc` decimal(10,2) DEFAULT NULL COMMENT '计算后的声明价值费',
  `cal_sfc` decimal(10,2) DEFAULT NULL COMMENT '计算后的地面运费',
  `cal_msc` decimal(10,2) DEFAULT NULL COMMENT '计算后的战保费',
  `cal_tax` decimal(10,2) DEFAULT NULL COMMENT '计算后的税',
  `cal_cca_fee` decimal(10,2) DEFAULT NULL COMMENT '计算后cca费用',
  `cal_other_fee` decimal(10,2) DEFAULT NULL COMMENT '计算后其他费用',
  `cal_total_other_fee` decimal(10,2) DEFAULT NULL COMMENT '计算后杂费合计',
  `cal_total_amount` decimal(10,2) DEFAULT NULL COMMENT '计算后总金额',
  `ancestors` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '部门祖级',
  `man_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'MAN号',
  `customs_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '海关状态 AC：预申报  CC：实际装载',
  `dept_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`) USING BTREE COMMENT '主键',
  KEY `flight_index` (`dep`,`dest`,`flight_no`,`flight_date`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='运单主单表';

